function validate([nums, edges]) {
  const n = Array.isArray(nums) ? nums.length : 0;
  if (n < 1 || n > 20000) return 'nums needs 1 to 2 * 10^4 values.';
  if (nums.some(v => !Number.isInteger(v) || v < 1 || v > 50)) return 'Each value is an integer from 1 to 50.';
  if (!Array.isArray(edges) || edges.length !== n - 1) return 'A tree on n nodes has exactly n - 1 edges.';
  const root = Array.from({ length: n }, (_, i) => i);
  const find = x => { while (root[x] !== x) { root[x] = root[root[x]]; x = root[x]; } return x; };
  for (const edge of edges) {
    if (!Array.isArray(edge) || edge.length !== 2 || edge.some(v => !Number.isInteger(v) || v < 0 || v >= n)) return 'Each edge is a pair of node numbers from 0 to n - 1.';
    const a = find(edge[0]), b = find(edge[1]);
    if (a === b) return 'The edges must form a tree (no cycles or repeated edges).';
    root[a] = b;
  }
  return null;
}

