function componentValue(nums, edges) {
  const n = nums.length;
  const graph = Array.from({ length: n }, () => []);
  for (const [a, b] of edges) {
    graph[a].push(b);
    graph[b].push(a);
  }

  const order = [];
  const parent = new Array(n).fill(-1);
  const visited = new Array(n).fill(false);
  const stack = [0];
  visited[0] = true;
  while (stack.length > 0) {
    const node = stack.pop();
    order.push(node);
    for (const next of graph[node]) {
      if (!visited[next]) {
        visited[next] = true;
        parent[next] = node;
        stack.push(next);
      }
    }
  }

  const total = nums.reduce((sum, value) => sum + value, 0);
  for (let parts = n; parts > 1; parts--) {
    if (total % parts !== 0) {
      continue;
    }
    const target = total / parts;
    const subtree = nums.slice();
    let ok = true;
    for (let i = n - 1; i > 0 && ok; i--) {
      const node = order[i];
      if (subtree[node] > target) {
        ok = false;
      } else if (subtree[node] < target) {
        subtree[parent[node]] += subtree[node];
      }
    }
    if (ok && subtree[0] === target) {
      return parts - 1;
    }
  }
  return 0;
}

