function componentValue(nums, edges) {
  const n = nums.length, m = edges.length;
  let best = 0;
  for (let mask = 0; mask < (1 << m); mask++) {
    // Keep the edges whose bit is 0, then label the pieces with a small union-find.
    const root = Array.from({ length: n }, (_, i) => i);
    const find = x => (root[x] === x ? x : (root[x] = find(root[x])));
    let removed = 0;
    for (let j = 0; j < m; j++) {
      if (mask & (1 << j)) removed++;
      else root[find(edges[j][0])] = find(edges[j][1]);
    }
    if (removed <= best) continue;
    const sums = new Map();
    for (let i = 0; i < n; i++) sums.set(find(i), (sums.get(find(i)) || 0) + nums[i]);
    if (new Set(sums.values()).size === 1) best = removed;
  }
  return best;
}

