function generate(rand, size) {
  const pick = limit => Math.floor(rand() * limit);
  const n = size === 'large' ? 2000 : 1 + pick(10);
  const nums = new Array(n);
  const pairs = [];
  if (rand() < 0.4) {
    // Plain random tree with random values.
    const top = size === 'large' ? 50 : 1 + pick(4);
    for (let i = 0; i < n; i++) nums[i] = 1 + pick(top);
    for (let i = 1; i < n; i++) pairs.push([pick(i), i]);
  } else {
    // Build pieces with one shared sum, grow each into a tree, then join the pieces with extra edges.
    const pieces = 1 + pick(size === 'large' ? 120 : n);
    let members = Array.from({ length: pieces }, () => []);
    for (let i = 0; i < n; i++) members[i < pieces ? i : pick(pieces)].push(i);
    if (Math.max(...members.map(list => list.length)) > 50 * Math.min(...members.map(list => list.length))) {
      // Sizes too uneven for one shared sum with values 1..50: deal the nodes out evenly instead.
      members = Array.from({ length: pieces }, () => []);
      for (let i = 0; i < n; i++) members[i % pieces].push(i);
    }
    const biggest = Math.max(...members.map(list => list.length));
    const smallest = Math.min(...members.map(list => list.length));
    // A piece of s nodes can sum to anything from s to 50 * s.
    const target = biggest + pick(50 * smallest - biggest + 1);
    for (const list of members) {
      // Spread target over the piece's nodes, each value in 1..50.
      let left = target;
      for (let j = 0; j < list.length; j++) {
        const rest = list.length - j - 1;
        const low = Math.max(1, left - 50 * rest), high = Math.min(50, left - rest);
        const value = j === list.length - 1 ? left : low + pick(high - low + 1);
        nums[list[j]] = value;
        left -= value;
      }
      for (let j = 1; j < list.length; j++) pairs.push([list[pick(j)], list[j]]);
    }
    for (let p = 1; p < pieces; p++) {
      const from = members[pick(p)], to = members[p];
      pairs.push([from[pick(from.length)], to[pick(to.length)]]);
    }
  }
  // Relabel nodes and shuffle edge order and direction.
  const label = Array.from({ length: n }, (_, i) => i);
  for (let i = n - 1; i > 0; i--) { const j = pick(i + 1); [label[i], label[j]] = [label[j], label[i]]; }
  const values = new Array(n);
  for (let i = 0; i < n; i++) values[label[i]] = nums[i];
  const edges = pairs.map(([a, b]) => (rand() < 0.5 ? [label[a], label[b]] : [label[b], label[a]]));
  for (let i = edges.length - 1; i > 0; i--) { const j = pick(i + 1); [edges[i], edges[j]] = [edges[j], edges[i]]; }
  return [values, edges];
}
